using System;using System.Collections.Generic;using Unity.Collections;using Unity.Mathematics;using Unity.Burst;using Unity.Jobs;using UnityEngine;
namespace FashionFit {
 public sealed class NativeClothTree:IDisposable {
  public struct Node{public float3 min,max;public int left,right,start,count;}
  public NativeArray<float3> Points;public NativeArray<int> Faces,Order;public NativeArray<Node> Nodes;
  public NativeClothTree(Vector3[] p,int[] faces){Points=new NativeArray<float3>(p.Length,Allocator.Persistent);Faces=new NativeArray<int>(faces,Allocator.Persistent);var order=new int[faces.Length/3];for(int i=0;i<order.Length;i++)order[i]=i;var nodes=new List<Node>();Build(nodes,order,0,order.Length,p,faces);Order=new NativeArray<int>(order,Allocator.Persistent);Nodes=new NativeArray<Node>(nodes.ToArray(),Allocator.Persistent);Refit(p);}
  static int Build(List<Node> nodes,int[] order,int start,int count,Vector3[] p,int[] f){int id=nodes.Count;nodes.Add(default);var n=new Node{left=-1,right=-1,start=start,count=count};if(count>8){Bounds b=new Bounds(p[f[order[start]*3]],Vector3.zero);for(int i=start;i<start+count;i++)for(int k=0;k<3;k++)b.Encapsulate(p[f[order[i]*3+k]]);int axis=b.size.x>b.size.y?(b.size.x>b.size.z?0:2):(b.size.y>b.size.z?1:2);Array.Sort(order,start,count,Comparer<int>.Create((a,c)=>((p[f[a*3]][axis]+p[f[a*3+1]][axis]+p[f[a*3+2]][axis])/3).CompareTo((p[f[c*3]][axis]+p[f[c*3+1]][axis]+p[f[c*3+2]][axis])/3)));int half=count/2;n.left=Build(nodes,order,start,half,p,f);n.right=Build(nodes,order,start+half,count-half,p,f);}nodes[id]=n;return id;}
  public void Refit(Vector3[] points){for(int i=0;i<points.Length;i++)Points[i]=points[i];new RefitJob{points=Points,faces=Faces,order=Order,nodes=Nodes}.Schedule().Complete();}
  [BurstCompile(CompileSynchronously=true)]struct RefitJob:IJob{[ReadOnly]public NativeArray<float3> points;[ReadOnly]public NativeArray<int> faces,order;public NativeArray<Node> nodes;public void Execute(){for(int i=nodes.Length-1;i>=0;i--){var n=nodes[i];if(n.left>=0){n.min=math.min(nodes[n.left].min,nodes[n.right].min);n.max=math.max(nodes[n.left].max,nodes[n.right].max);}else{n.min=float.PositiveInfinity;n.max=float.NegativeInfinity;for(int k=n.start;k<n.start+n.count;k++)for(int a=0;a<3;a++){float3 p=points[faces[order[k]*3+a]];n.min=math.min(n.min,p);n.max=math.max(n.max,p);}}nodes[i]=n;}}}
  public void Dispose(){if(Points.IsCreated)Points.Dispose();if(Faces.IsCreated)Faces.Dispose();if(Order.IsCreated)Order.Dispose();if(Nodes.IsCreated)Nodes.Dispose();}
 }
 public static class NativeGarmentContact {
  public static float3 Triangle(float3 p,float3 a,float3 b,float3 c){float3 ab=b-a,ac=c-a,ap=p-a;float d1=math.dot(ab,ap),d2=math.dot(ac,ap);if(d1<=0&&d2<=0)return a;float3 bp=p-b;float d3=math.dot(ab,bp),d4=math.dot(ac,bp);if(d3>=0&&d4<=d3)return b;float vc=d1*d4-d3*d2;if(vc<=0&&d1>=0&&d3<=0)return a+ab*(d1/(d1-d3));float3 cp=p-c;float d5=math.dot(ab,cp),d6=math.dot(ac,cp);if(d6>=0&&d5<=d6)return c;float vb=d5*d2-d1*d6;if(vb<=0&&d2>=0&&d6<=0)return a+ac*(d2/(d2-d6));float va=d3*d6-d5*d4;if(va<=0&&d4-d3>=0&&d5-d6>=0)return b+(c-b)*((d4-d3)/((d4-d3)+(d5-d6)));float sum=va+vb+vc;if(math.abs(sum)<1e-12f)return a;return a+ab*(vb/sum)+ac*(vc/sum);}
  public static float Bounds(float3 p,NativeClothTree.Node n){float3 d=math.max(math.max(n.min-p,p-n.max),0);return math.lengthsq(d);}
  public static float3 Cloth(float3 p,float3 previous,NativeArray<float3> points,NativeArray<int> faces,NativeArray<int> order,NativeArray<NativeClothTree.Node> nodes,float thickness,bool outward){if(nodes.Length==0||Bounds(p,nodes[0])>.002025f)return p;float best=.002025f;float3 hit=p,normal=0;var stack=new FixedList512Bytes<int>();stack.Add(0);while(stack.Length>0){int id=stack[stack.Length-1];stack.RemoveAt(stack.Length-1);var n=nodes[id];if(Bounds(p,n)>best)continue;if(n.left>=0){float left=Bounds(p,nodes[n.left]),right=Bounds(p,nodes[n.right]);if(left<right){if(right<best)stack.Add(n.right);if(left<best)stack.Add(n.left);}else{if(left<best)stack.Add(n.left);if(right<best)stack.Add(n.right);}continue;}for(int k=n.start;k<n.start+n.count;k++){int f=order[k]*3;float3 a=points[faces[f]],b=points[faces[f+1]],c=points[faces[f+2]],q=Triangle(p,a,b,c);float d=math.lengthsq(p-q);if(d<best){best=d;hit=q;normal=math.normalizesafe(math.cross(b-a,c-a));}}}if(math.lengthsq(normal)<.5f)return p;float distance=math.sqrt(best),signed=math.dot(p-hit,normal),old=math.dot(previous-hit,normal),side=outward?1:(old>=0?1:-1);if(outward&&signed<thickness)p+=normal*(thickness-signed);else if(distance<thickness)p=hit+math.normalizesafe(p-hit,normal*side)*thickness;else if(signed*old<0)p+=normal*(side*(thickness-signed*side));return p;}
  public static float3 Field(float3 p,NativeArray<float> field,float3 origin,float cell,int nx,int ny,int nz,float margin){for(int pass=0;pass<3;pass++){float3 q=(p-origin)/cell;int3 i=(int3)math.floor(q);if(math.any(i<0)||i.x>=nx-1||i.y>=ny-1||i.z>=nz-1)return p;float3 uv=q-i;int a0=(i.x*ny+i.y)*nz+i.z,b0=a0+ny*nz,c0=a0+nz,d0=b0+nz;float a=field[a0],b=field[b0],c=field[c0],d=field[d0],e=field[a0+1],f=field[b0+1],g=field[c0+1],h=field[d0+1];float u=uv.x,v=uv.y,w=uv.z,s0=math.lerp(math.lerp(a,b,u),math.lerp(c,d,u),v),s1=math.lerp(math.lerp(e,f,u),math.lerp(g,h,u),v),distance=math.lerp(s0,s1,w);if(distance>=margin)return p;float3 n=new float3(math.lerp(math.lerp(b-a,d-c,v),math.lerp(f-e,h-g,v),w),math.lerp(math.lerp(c-a,d-b,u),math.lerp(g-e,h-f,u),w),s1-s0)/cell;p+=math.normalizesafe(n,new float3(0,1,0))*math.min(.08f,margin-distance);}return p;}
 }
}
